// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import { armedPullRequestNumber, armedRefusal } from "../../../scripts/auto-merge-guard.mjs";

describe("auto-merge-guard", () => {
  // The PR #37 case: an open pull request already promised to merge itself.
  // Pushing onto it races a decision that was made without this commit.
  it("names an open pull request with auto-merge armed", () => {
    const raw = JSON.stringify({
      number: 37,
      state: "OPEN",
      autoMergeRequest: { enabledAt: "2026-07-27T07:51:12Z" },
    });

    expect(armedPullRequestNumber(raw)).toBe(37);
  });

  // The ordinary case. Nobody promised anything, so pushing is free.
  it("allows a pull request nobody armed", () => {
    const raw = JSON.stringify({
      number: 42,
      state: "OPEN",
      autoMergeRequest: null,
    });

    expect(armedPullRequestNumber(raw)).toBeNull();
  });

  // A merged or closed pull request cannot merge again, so it constrains
  // nothing. Blocking here would refuse a push that is entirely safe.
  it("ignores a pull request that is no longer open", () => {
    const raw = JSON.stringify({
      number: 37,
      state: "MERGED",
      autoMergeRequest: { enabledAt: "2026-07-27T07:51:12Z" },
    });

    expect(armedPullRequestNumber(raw)).toBeNull();
  });

  // The load-bearing one. `gh` missing, unauthenticated, or the branch having
  // no pull request all arrive here as no answer — and a guard that blocks on
  // its own blindness is unsatisfiable, which teaches people to bypass it.
  it("permits the push when it cannot see an answer", () => {
    expect(armedPullRequestNumber(null)).toBeNull();
    expect(armedPullRequestNumber("")).toBeNull();
    expect(armedPullRequestNumber("not json at all")).toBeNull();
    expect(armedPullRequestNumber("{}")).toBeNull();
  });

  // A refusal must name the party that has to move and the command that moves
  // them (ADR-0045 clause 4), or the only way past it is to bypass the guard.
  it("tells the reader exactly how to satisfy it", () => {
    const message = armedRefusal(38, "fleet/stalled-work-report");

    expect(message).toContain("#38");
    expect(message).toContain("fleet/stalled-work-report");
    expect(message).toContain("gh pr merge 38 --disable-auto");
  });
});
